#define NS_SANDBOX_ACTIVE              (1u << 0)
#define NS_SANDBOX_ALLOW_SCRIPTS       (1u << 1)
#define NS_SANDBOX_ALLOW_FORMS         (1u << 2)
#define NS_SANDBOX_ALLOW_SAME_ORIGIN   (1u << 3)
#define NS_SANDBOX_ALLOW_POPUPS        (1u << 4)
#define NS_SANDBOX_ALLOW_MODALS        (1u << 5)
#define NS_SANDBOX_ALLOW_TOP_NAV       (1u << 6)
#define NS_SANDBOX_ALLOW_TOP_NAV_UA    (1u << 7)
#define NS_SANDBOX_ALLOW_DOWNLOADS     (1u << 8)
#define NS_SANDBOX_ALLOW_POPUPS_ESCAPE (1u << 9)
#define NS_SANDBOX_ALLOW_POINTER_LOCK  (1u << 10)
#define NS_SANDBOX_ALLOW_PRESENTATION  (1u << 11)
#define NS_SANDBOX_ALLOW_ORIENTATION   (1u << 12)
#define NS_FRAME_CROSS_ORIGIN          (1u << 13)

static const struct { const char *token; unsigned flag; } ns_sandbox_tokens[] = {
    { "allow-scripts",                          NS_SANDBOX_ALLOW_SCRIPTS },
    { "allow-forms",                            NS_SANDBOX_ALLOW_FORMS },
    { "allow-same-origin",                      NS_SANDBOX_ALLOW_SAME_ORIGIN },
    { "allow-popups",                           NS_SANDBOX_ALLOW_POPUPS },
    { "allow-modals",                           NS_SANDBOX_ALLOW_MODALS },
    { "allow-top-navigation",                   NS_SANDBOX_ALLOW_TOP_NAV },
    { "allow-top-navigation-by-user-activation", NS_SANDBOX_ALLOW_TOP_NAV_UA },
    { "allow-downloads",                        NS_SANDBOX_ALLOW_DOWNLOADS },
    { "allow-popups-to-escape-sandbox",         NS_SANDBOX_ALLOW_POPUPS_ESCAPE },
    { "allow-pointer-lock",                     NS_SANDBOX_ALLOW_POINTER_LOCK },
    { "allow-presentation",                     NS_SANDBOX_ALLOW_PRESENTATION },
    { "allow-orientation-lock",                 NS_SANDBOX_ALLOW_ORIENTATION },
};

/* Parses an iframe sandbox attribute into NS_SANDBOX_* flags; always sets ACTIVE. */
static unsigned
ns_sandbox_parse_tokens(const char *val)
{
    unsigned flags = NS_SANDBOX_ACTIVE;
    if (!val) return flags;
    const char *p = val;
    while (*p) {
        while (*p && g_ascii_isspace((guchar)*p)) p++;
        const char *s = p;
        while (*p && !g_ascii_isspace((guchar)*p)) p++;
        gsize len = (gsize)(p - s);
        if (len == 0) continue;
        for (gsize i = 0; i < G_N_ELEMENTS(ns_sandbox_tokens); i++) {
            const char *t = ns_sandbox_tokens[i].token;
            if (strlen(t) == len && g_ascii_strncasecmp(s, t, len) == 0) {
                flags |= ns_sandbox_tokens[i].flag;
                break;
            }
        }
    }
    return flags;
}

/* Intersects sandbox flags of all ancestor iframes; returns 0 when none are sandboxed. */
static unsigned
ns_iframe_effective_sandbox(const ns_node *node)
{
    unsigned flags = 0;
    gboolean any = FALSE;
    for (const ns_node *p = node; p; p = p->parent) {
        if (!ns_node_is_element_named(p, "iframe")) continue;
        const char *val = ns_element_get_attr(p, "sandbox");
        if (!val) continue;
        unsigned f = ns_sandbox_parse_tokens(val);
        if (!any) { flags = f; any = TRUE; }
        else flags &= f;
    }
    return any ? (flags | NS_SANDBOX_ACTIVE) : 0;
}

/* True when an enclosing sandboxed iframe lacks allow-forms. */
static gboolean
ns_node_sandbox_blocks_forms(const ns_node *node)
{
    unsigned sb = ns_iframe_effective_sandbox(node);
    return (sb & NS_SANDBOX_ACTIVE) && !(sb & NS_SANDBOX_ALLOW_FORMS);
}

/* Legacy MediaQueryList.addListener: registers the callback as a "change" listener. */
static JSValue
ns_mql_addListener(JSContext *ctx, JSValueConst this_val,
                   int argc, JSValueConst *argv)
{
    if (argc < 1 || !JS_IsFunction(ctx, argv[0])) return JS_UNDEFINED;
    JSValueConst args[2] = { JS_NewString(ctx, "change"), argv[0] };
    JSValue r = ns_target_addEventListener(ctx, this_val, 2, args);
    JS_FreeValue(ctx, args[0]);
    return r;
}

/* Legacy MediaQueryList.removeListener: removes a "change" listener. */
static JSValue
ns_mql_removeListener(JSContext *ctx, JSValueConst this_val,
                      int argc, JSValueConst *argv)
{
    if (argc < 1) return JS_UNDEFINED;
    JSValueConst args[2] = { JS_NewString(ctx, "change"), argv[0] };
    JSValue r = ns_target_removeEventListener(ctx, this_val, 2, args);
    JS_FreeValue(ctx, args[0]);
    return r;
}

/* Per-evaluation script time budget from config in microseconds, defaulting to 60 s. */
static gint64
ns_js_eval_budget_us(void)
{
    const ns_config *c = ns_config_get();
    int ms = c ? c->js_eval_budget_ms : 60000;
    if (ms <= 0) ms = 60000;
    if (ms > NS_JS_EVAL_BUDGET_MAX_MS) ms = NS_JS_EVAL_BUDGET_MAX_MS;
    return (gint64)ms * 1000LL;
}

#define NS_JS_MONITOR_LIMIT_US (60LL * 1000000LL)

/* QuickJS interrupt check: halts on worker close, monitor deadline or eval budget expiry. */
static int
ns_js_interrupt(void *opaque)
{
    ns_js *js = opaque;
    if (!js) return 0;
    if (js->halted) return 1;
    if (js->worker_host && g_atomic_int_get(&js->worker_host->closing)) {
        js->halted = TRUE;
        return 1;
    }
    gint64 now = g_get_monotonic_time();
    if (js->js_monitor_deadline_us != 0 && now > js->js_monitor_deadline_us) {
        js->halted = TRUE;
        g_warning("[js] monitor: page JavaScript ran longer than %d s — halting it",
                  (int)(NS_JS_MONITOR_LIMIT_US / 1000000LL));
        return 1;
    }
    if (js->eval_deadline_us == 0) return 0;
    return now > js->eval_deadline_us ? 1 : 0;
}

static int
ns_js_interrupt_ctx_cb(JSContext *ctx, void *opaque)
{
    (void)ctx;
    return ns_js_interrupt(opaque);
}

static int
ns_js_interrupt_rt_cb(JSRuntime *rt, void *opaque)
{
    (void)rt;
    return ns_js_interrupt(opaque);
}

static gboolean
ns_js_in_pump(const ns_js *js)
{
    return js && js->in_pump;
}

/* Extends eval and monitor deadlines by time spent pumping a nested main loop. */
static void
ns_js_credit_pumped_time(ns_js *js, gint64 pump_start_us)
{
    if (!js) return;
    gint64 pumped_us = g_get_monotonic_time() - pump_start_us;
    if (pumped_us <= 0) return;
    if (js->eval_deadline_us != 0)
        js->eval_deadline_us += pumped_us;
    if (js->js_monitor_deadline_us != 0)
        js->js_monitor_deadline_us += pumped_us;
}

typedef struct {
    GMainLoop   *loop;
    ns_response *resp;
    GError      *err;
    gboolean     done;
} ns_js_pumped_fetch;

static void
ns_js_pumped_fetch_done(GObject *src, GAsyncResult *result, gpointer user_data)
{
    (void)src;
    ns_js_pumped_fetch *pf = user_data;
    pf->resp = ns_net_fetch_finish(result, &pf->err);
    pf->done = TRUE;
    if (pf->loop) g_main_loop_quit(pf->loop);
}

/* Synchronous GET; on the main thread pumps a nested loop so the budget isn't charged. */
static ns_response *
ns_js_fetch_resource(ns_js *js, const char *url, const char *top_url,
                     const char *const *headers, ns_fetch_destination dest,
                     ns_fetch_policy *policy, GError **error)
{
    if (!js || js->worker_host)
        return ns_net_request_blocking(url, top_url, "GET", NULL, 0, NULL,
                                       headers, dest, policy, NULL, error);

    ns_js_pumped_fetch pf = {0};
    pf.loop = g_main_loop_new(ns_engine_context(), FALSE);
    ns_net_request_async(url, top_url, "GET", NULL, 0, NULL, headers, dest,
                         policy, NULL,
                         ns_js_pumped_fetch_done, &pf);
    gboolean saved = js->in_pump;
    js->in_pump = TRUE;
    gint64 pump_start_us = g_get_monotonic_time();
    if (!pf.done)
        g_main_loop_run(pf.loop);
    ns_js_credit_pumped_time(js, pump_start_us);
    js->in_pump = saved;
    g_main_loop_unref(pf.loop);
    if (pf.err) {
        if (error) *error = pf.err;
        else g_error_free(pf.err);
    }
    return pf.resp;
}

typedef struct ns_budget_guard {
    gint64 saved;
} ns_budget_guard;

/* Starts a script budget scope, arming the monitor deadline for the outermost one. */
static void
ns_js_budget_push(ns_js *js, ns_budget_guard *g)
{
    if (!js || !g) return;
    g->saved = js->eval_deadline_us;
    gint64 now = g_get_monotonic_time();
    if (g->saved == 0)
        js->js_monitor_deadline_us = now + NS_JS_MONITOR_LIMIT_US;
    gint64 fresh = now + ns_js_eval_budget_us();
    if (g->saved == 0 || fresh < g->saved)
        js->eval_deadline_us = fresh;
}

/* Restores the saved eval deadline; clears the monitor deadline at outermost scope. */
static void
ns_js_budget_pop(ns_js *js, ns_budget_guard *g)
{
    if (!js || !g) return;
    js->eval_deadline_us = g->saved;
    if (g->saved == 0)
        js->js_monitor_deadline_us = 0;
}

typedef struct ns_listener {
    const ns_node *target;
    char          *type;
    JSValue        cb;
    JSValue        signal;
    gboolean       capture;
    gboolean       once;
    gboolean       passive;
    gboolean       window_level;
} ns_listener;

typedef struct ns_timer {
    ns_js   *js;
    JSContext *ctx;
    JSValue  cb;
    char    *code;
    int      id;
    guint    glib_source;
    gboolean is_interval;
    gboolean is_idle;
    gboolean immediate;
    gboolean firing;
    gint64   due_us;
    gint64   idle_deadline_us;
    int      nesting_level;
    int      interval_ms;
    int      extra_args_count;
    JSValue *extra_args;
    ns_node *frame;
} ns_timer;

typedef struct ns_raf_entry {
    int      id;
    JSContext *ctx;
    JSValue  cb;
    gboolean video_frame;
    ns_node *frame;
} ns_raf_entry;

/* Returns the iframe node owning a realm context, falling back to the current rAF frame. */
static ns_node *
ns_js_context_frame(ns_js *js, JSContext *ctx)
{
    if (!js || !ctx) return NULL;
    if (js->frame_contexts) {
        GHashTableIter iter;
        gpointer key, value;
        g_hash_table_iter_init(&iter, js->frame_contexts);
        while (g_hash_table_iter_next(&iter, &key, &value))
            if (value == ctx) return key;
    }
    return js->raf_frame_ctx;
}

uint32_t
ns_js_array_length(JSContext *ctx, JSValueConst arr)
{
    uint32_t len = 0;
    JSValue lv = JS_GetPropertyStr(ctx, arr, "length");
    JS_ToUint32(ctx, &len, lv);
    JS_FreeValue(ctx, lv);
    return len;
}

/* Reads obj[key] as a boolean; was_set reports whether it was defined. */
gboolean
ns_js_get_bool_prop(JSContext *ctx, JSValueConst obj, const char *key,
                    gboolean *was_set)
{
    JSValue v = JS_GetPropertyStr(ctx, obj, key);
    gboolean defined = !JS_IsUndefined(v);
    gboolean truthy = defined && JS_ToBool(ctx, v) > 0;
    JS_FreeValue(ctx, v);
    if (was_set) *was_set = defined;
    return truthy;
}

/* Reads obj[key] as int32, returning fallback when undefined or null. */
static int32_t
ns_js_get_int32_prop(JSContext *ctx, JSValueConst obj, const char *key,
                     int32_t fallback)
{
    JSValue v = JS_GetPropertyStr(ctx, obj, key);
    int32_t r = fallback;
    if (!JS_IsUndefined(v) && !JS_IsNull(v)) JS_ToInt32(ctx, &r, v);
    JS_FreeValue(ctx, v);
    return r;
}

/* Reads obj[key] as a double, returning fallback when undefined or null. */
static double
ns_js_get_double_prop(JSContext *ctx, JSValueConst obj, const char *key,
                      double fallback)
{
    JSValue v = JS_GetPropertyStr(ctx, obj, key);
    double r = fallback;
    if (!JS_IsUndefined(v) && !JS_IsNull(v)) JS_ToFloat64(ctx, &r, v);
    JS_FreeValue(ctx, v);
    return r;
}

/* Returns a g_strdup copy of obj[key] if it is a string, else NULL; caller frees. */
static char *
ns_js_get_string_prop(JSContext *ctx, JSValueConst obj, const char *key)
{
    JSValue v = JS_GetPropertyStr(ctx, obj, key);
    char *out = NULL;
    if (JS_IsString(v)) {
        const char *s = JS_ToCString(ctx, v);
        if (s) { out = g_strdup(s); JS_FreeCString(ctx, s); }
    }
    JS_FreeValue(ctx, v);
    return out;
}

/* Borrows the bytes of an ArrayBuffer or view; out_holder keeps the buffer alive. */
static gboolean
ns_js_bytes_view(JSContext *ctx, JSValueConst value, const uint8_t **out_data,
                 size_t *out_len, JSValue *out_holder)
{
    if (out_data) *out_data = NULL;
    if (out_len) *out_len = 0;
    if (out_holder) *out_holder = JS_UNDEFINED;

    if (JS_IsArrayBuffer(value)) {
        size_t total = 0;
        uint8_t *base = JS_GetArrayBuffer(ctx, &total, value);
        if (base) {
            if (out_data) *out_data = base;
            if (out_len) *out_len = total;
            if (out_holder) *out_holder = JS_DupValue(ctx, value);
            return TRUE;
        }
        return FALSE;
    }

    if (!JS_IsObject(value)) return FALSE;

    JSValue buf = JS_GetPropertyStr(ctx, value, "buffer");
    if (JS_IsException(buf)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        return FALSE;
    }
    if (!JS_IsArrayBuffer(buf)) {
        JS_FreeValue(ctx, buf);
        return FALSE;
    }

    JSValue off_v = JS_GetPropertyStr(ctx, value, "byteOffset");
    JSValue len_v = JS_GetPropertyStr(ctx, value, "byteLength");
    if (JS_IsException(off_v) || JS_IsException(len_v)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        JS_FreeValue(ctx, off_v);
        JS_FreeValue(ctx, len_v);
        JS_FreeValue(ctx, buf);
        return FALSE;
    }
    gboolean ok = JS_IsNumber(off_v) && JS_IsNumber(len_v);
    uint64_t byte_off = 0, byte_len = 0;
    if (ok && (JS_ToIndex(ctx, &byte_off, off_v) < 0 ||
               JS_ToIndex(ctx, &byte_len, len_v) < 0)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        ok = FALSE;
    }
    JS_FreeValue(ctx, off_v);
    JS_FreeValue(ctx, len_v);
    if (!ok) {
        JS_FreeValue(ctx, buf);
        return FALSE;
    }

    size_t total = 0;
    uint8_t *base = JS_GetArrayBuffer(ctx, &total, buf);
    if (!base || byte_off > total || byte_len > total - byte_off) {
        JS_FreeValue(ctx, buf);
        return FALSE;
    }
    if (out_data) *out_data = base + byte_off;
    if (out_len) *out_len = (size_t)byte_len;
    if (out_holder) *out_holder = buf;
    else JS_FreeValue(ctx, buf);
    return TRUE;
}

/* NUL-terminated copy of a byte range, refusing bodies over NS_JS_BODY_BYTES_MAX. */
static char *
ns_js_copy_bytes(const uint8_t *data, gsize len)
{
    if (len > NS_JS_BODY_BYTES_MAX) return NULL;
    char *out = g_malloc(len + 1);
    if (len > 0 && data) memcpy(out, data, len);
    out[len] = '\0';
    return out;
}

/* Extracts a request body from a string, buffer source or Blob as a new byte copy. */
static char *
ns_js_body_bytes(JSContext *ctx, JSValueConst value, gsize *out_len)
{
    if (out_len) *out_len = 0;
    if (JS_IsUndefined(value) || JS_IsNull(value)) return NULL;

    if (JS_IsString(value)) {
        size_t slen = 0;
        const char *s = JS_ToCStringLen(ctx, &slen, value);
        if (!s) return NULL;
        char *copy = ns_js_copy_bytes((const uint8_t *)s, (gsize)slen);
        JS_FreeCString(ctx, s);
        if (copy && out_len) *out_len = (gsize)slen;
        return copy;
    }

    const uint8_t *data = NULL;
    size_t len = 0;
    JSValue holder = JS_UNDEFINED;
    if (ns_js_bytes_view(ctx, value, &data, &len, &holder)) {
        char *copy = ns_js_copy_bytes(data, (gsize)len);
        JS_FreeValue(ctx, holder);
        if (copy && out_len) *out_len = (gsize)len;
        return copy;
    }

    if (JS_IsObject(value)) {
        JSValue b = JS_GetPropertyStr(ctx, value, "_b");
        if (JS_IsException(b)) {
            JS_FreeValue(ctx, JS_GetException(ctx));
            return NULL;
        }
        gboolean has_blob_bytes = !JS_IsUndefined(b) && !JS_IsNull(b);
        JS_FreeValue(ctx, b);
        if (has_blob_bytes) return ns_blob_bytes_as_string(ctx, value, out_len);
    }

    return NULL;
}

/* Duck-types a FormData polyfill object by its _entries array and append/getAll. */
static gboolean
ns_js_value_is_form_data(JSContext *ctx, JSValueConst v)
{
    if (!JS_IsObject(v) || JS_IsFunction(ctx, v)) return FALSE;
    JSValue e = JS_GetPropertyStr(ctx, v, "_entries");
    gboolean is_arr = JS_IsArray(e);
    JS_FreeValue(ctx, e);
    if (!is_arr) return FALSE;
    JSValue a = JS_GetPropertyStr(ctx, v, "append");
    JSValue s = JS_GetPropertyStr(ctx, v, "getAll");
    gboolean ok = JS_IsFunction(ctx, a) && JS_IsFunction(ctx, s);
    JS_FreeValue(ctx, a);
    JS_FreeValue(ctx, s);
    return ok;
}

/* Duck-types a URLSearchParams polyfill object by its _p array and append/getAll. */
static gboolean
ns_js_value_is_url_search_params(JSContext *ctx, JSValueConst v)
{
    if (!JS_IsObject(v) || JS_IsFunction(ctx, v)) return FALSE;
    JSValue p = JS_GetPropertyStr(ctx, v, "_p");
    gboolean is_arr = JS_IsArray(p);
    JS_FreeValue(ctx, p);
    if (!is_arr) return FALSE;
    JSValue a = JS_GetPropertyStr(ctx, v, "append");
    JSValue s = JS_GetPropertyStr(ctx, v, "getAll");
    gboolean ok = JS_IsFunction(ctx, a) && JS_IsFunction(ctx, s);
    JS_FreeValue(ctx, a);
    JS_FreeValue(ctx, s);
    return ok;
}

/* Encodes FormData as multipart/form-data with a fresh boundary; caller frees both outputs. */
static char *
ns_js_form_data_serialize(JSContext *ctx, JSValueConst fd,
                          gsize *out_len, char **out_content_type)
{
    char *boundary = ns_multipart_boundary();
    if (out_content_type)
        *out_content_type = g_strdup_printf(
            "multipart/form-data; boundary=%s", boundary);

    GString *body = g_string_new(NULL);
    JSValue entries = JS_GetPropertyStr(ctx, fd, "_entries");
    if (JS_IsArray(entries)) {
        uint32_t n = ns_js_array_length(ctx, entries);
        for (uint32_t i = 0; i < n; i++) {
            JSValue pair = JS_GetPropertyUint32(ctx, entries, i);
            if (!JS_IsArray(pair)) { JS_FreeValue(ctx, pair); continue; }
            JSValue k = JS_GetPropertyUint32(ctx, pair, 0);
            JSValue v = JS_GetPropertyUint32(ctx, pair, 1);
            JSValue fname_override = JS_GetPropertyUint32(ctx, pair, 2);
            const char *ks = JS_ToCString(ctx, k);

            JSValue b_priv = JS_IsObject(v)
                ? JS_GetPropertyStr(ctx, v, "_b") : JS_UNDEFINED;
            gboolean is_blob = !JS_IsUndefined(b_priv) && !JS_IsNull(b_priv);
            JS_FreeValue(ctx, b_priv);

            g_string_append_printf(body, "--%s\r\n", boundary);
            g_string_append(body, "Content-Disposition: form-data; name=\"");
            ns_multipart_quote_field(body, ks ? ks : "");
            g_string_append_c(body, '"');

            if (is_blob) {
                JSValue fname_v = !JS_IsUndefined(fname_override)
                    ? JS_DupValue(ctx, fname_override)
                    : JS_GetPropertyStr(ctx, v, "name");
                const char *fname = JS_IsString(fname_v)
                    ? JS_ToCString(ctx, fname_v) : NULL;
                g_string_append(body, "; filename=\"");
                ns_multipart_quote_field(body, fname ? fname : "blob");
                g_string_append(body, "\"\r\n");
                if (fname) JS_FreeCString(ctx, fname);
                JS_FreeValue(ctx, fname_v);

                JSValue type_v = JS_GetPropertyStr(ctx, v, "type");
                const char *type = JS_IsString(type_v)
                    ? JS_ToCString(ctx, type_v) : NULL;
                GString *ct = g_string_new(NULL);
                for (const char *tp = type; tp && *tp; tp++) {
                    unsigned char c = (unsigned char)*tp;
                    if (c >= 0x20 && c != 0x7f) g_string_append_c(ct, (char)c);
                }
                g_string_append_printf(body, "Content-Type: %s\r\n\r\n",
                    ct->len ? ct->str : "application/octet-stream");
                g_string_free(ct, TRUE);
                if (type) JS_FreeCString(ctx, type);
                JS_FreeValue(ctx, type_v);

                gsize blob_len = 0;
                char *blob_bytes = ns_blob_bytes_as_string(ctx, v, &blob_len);
                if (blob_bytes) {
                    g_string_append_len(body, blob_bytes, (gssize)blob_len);
                    g_free(blob_bytes);
                }
                g_string_append(body, "\r\n");
            } else {
                size_t vlen = 0;
                const char *vs = JS_ToCStringLen(ctx, &vlen, v);
                g_string_append(body, "\r\n\r\n");
                if (vs) g_string_append_len(body, vs, (gssize)vlen);
                if (vs) JS_FreeCString(ctx, vs);
                g_string_append(body, "\r\n");
            }

            if (ks) JS_FreeCString(ctx, ks);
            JS_FreeValue(ctx, k);
            JS_FreeValue(ctx, v);
            JS_FreeValue(ctx, fname_override);
            JS_FreeValue(ctx, pair);
        }
    }
    JS_FreeValue(ctx, entries);
    g_string_append_printf(body, "--%s--\r\n", boundary);
    g_free(boundary);
    if (out_len) *out_len = body->len;
    return g_string_free(body, FALSE);
}

/* Serializes URLSearchParams via toString() as a urlencoded body; caller frees outputs. */
static char *
ns_js_usp_serialize(JSContext *ctx, JSValueConst usp,
                    gsize *out_len, char **out_content_type)
{
    if (out_content_type)
        *out_content_type =
            g_strdup("application/x-www-form-urlencoded;charset=UTF-8");
    JSValue ts_fn = JS_GetPropertyStr(ctx, usp, "toString");
    JSValue str = JS_IsFunction(ctx, ts_fn)
        ? JS_Call(ctx, ts_fn, usp, 0, NULL) : JS_NewString(ctx, "");
    JS_FreeValue(ctx, ts_fn);
    if (JS_IsException(str)) {
        JS_FreeValue(ctx, JS_GetException(ctx));
        if (out_len) *out_len = 0;
        return g_strdup("");
    }
    size_t l = 0;
    const char *s = JS_ToCStringLen(ctx, &l, str);
    char *out = s ? g_strndup(s, l) : g_strdup("");
    if (s) JS_FreeCString(ctx, s);
    JS_FreeValue(ctx, str);
    if (out_len) *out_len = out ? strlen(out) : 0;
    return out;
}

/* Rejects with an Error, splitting a "NameError: msg" prefix into name; frees resolvers. */
void
ns_js_promise_reject(JSContext *ctx, JSValue resolvers[2], const char *message)
{
    JSValue err = JS_NewError(ctx);
    const char *colon = strchr(message, ':');
    gsize name_len = colon ? (gsize)(colon - message) : strlen(message);
    gboolean is_dom_name = name_len > 5 && name_len < 64 &&
        memcmp(message + name_len - 5, "Error", 5) == 0;
    for (gsize i = 0; is_dom_name && i < name_len; i++)
        if (!g_ascii_isalnum((guchar)message[i])) is_dom_name = FALSE;
    if (is_dom_name) {
        char *nm = g_strndup(message, name_len);
        JS_SetPropertyStr(ctx, err, "name", JS_NewString(ctx, nm));
        g_free(nm);
        const char *rest = colon ? colon + 1 : message;
        while (*rest == ' ') rest++;
        JS_SetPropertyStr(ctx, err, "message", JS_NewString(ctx, rest));
    } else {
        JS_SetPropertyStr(ctx, err, "message", JS_NewString(ctx, message));
    }
    JS_Call(ctx, resolvers[1], JS_UNDEFINED, 1, &err);
    JS_FreeValue(ctx, err);
    JS_FreeValue(ctx, resolvers[0]);
    JS_FreeValue(ctx, resolvers[1]);
}

/* True if the element's tag matches any name in a NULL-terminated list, case-insensitively. */
static gboolean
ns_node_name_is_any_of(const ns_node *n, const char *const *tags)
{
    if (!n || n->kind != NS_NODE_ELEMENT || !n->name) return FALSE;
    for (; *tags; tags++)
        if (g_ascii_strcasecmp(n->name, *tags) == 0) return TRUE;
    return FALSE;
}

/* True if the node is in the main document or the current document tree. */
static gboolean
ns_js_node_in_page(const ns_js *js, const ns_node *node)
{
    if (!js || !node || !js->current_doc) return FALSE;
    const ns_node *page = js->main_document ? js->main_document
                                            : js->current_doc;
    for (const ns_node *p = node; p; p = p->parent)
        if (p == page || p == js->current_doc) return TRUE;
    return FALSE;
}

/* Destroys a GSource by id on the engine's main context. */
static void
ns_js_source_remove(ns_js *js, guint id)
{
    if (!id) return;
    GMainContext *context = js && js->main_context ? js->main_context
                                                   : g_main_context_default();
    GSource *source = g_main_context_find_source_by_id(context, id);
    if (source) g_source_destroy(source);
}

/* Frees a timer record, its callback, code and extra args, and removes its GSource. */
static void
ns_timer_free(gpointer data)
{
    ns_timer *t = data;
    if (!t) return;
    if (t->immediate && t->js && t->js->n_immediate_timers > 0)
        t->js->n_immediate_timers--;
    if (t->glib_source) ns_js_source_remove(t->js, t->glib_source);
    JSContext *ctx = t->ctx ? t->ctx : t->js->ctx;
    JS_FreeValue(ctx, t->cb);
    g_free(t->code);
    for (int i = 0; i < t->extra_args_count; i++)
        JS_FreeValue(ctx, t->extra_args[i]);
    g_free(t->extra_args);
    g_free(t);
}

static guint
ns_js_attach_timeout(ns_js *js, guint ms, GSourceFunc func, gpointer data)
{
    GSource *source = g_timeout_source_new(ms);
    g_source_set_callback(source, func, data, NULL);
    guint id = g_source_attach(source, js && js->main_context ? js->main_context : NULL);
    g_source_unref(source);
    return id;
}

static guint
ns_js_attach_idle(ns_js *js, GSourceFunc func, gpointer data)
{
    GSource *source = g_idle_source_new();
    g_source_set_callback(source, func, data, NULL);
    guint id = g_source_attach(source, js && js->main_context ? js->main_context : NULL);
    g_source_unref(source);
    return id;
}

static void ns_storage_drain_deferred_events(ns_js *js);
static JSContext *ns_js_window_realm(ns_js *js, JSValueConst window);
static const ns_csp *ns_js_realm_csp(ns_js *js, JSContext *ctx);
static char *ns_js_caller_origin(ns_js *js, JSContext *ctx);
static char *ns_js_caller_document_url(ns_js *js, JSContext *ctx);
static gboolean ns_js_caller_unknown(ns_js *js, JSContext *caller);
static char *ns_js_realm_origin(ns_js *js, JSContext *realm);
static JSContext *ns_js_handler_realm(ns_js *js, const ns_node *n);
static ns_node *ns_js_node_frame(const ns_node *node);
static void ns_js_report_pending_rejections(ns_js *js);
static void ns_js_drop_pending_rejections(ns_js *js);

#define NS_MICROTASK_SLICE_US 8000
#define NS_MICROTASK_SLICE_JOBS 256

static gboolean
ns_microtask_drain_idle(gpointer data)
{
    ns_js *js = data;
    js->microtask_source = 0;
    ns_drain_microtasks(js);
    return G_SOURCE_REMOVE;
}

/* Schedules an idle drain of pending QuickJS jobs if none is queued. */
static void
ns_schedule_microtask_drain(ns_js *js)
{
    if (!js || js->halted || js->microtask_source ||
        !JS_IsJobPending(js->rt))
        return;
    js->microtask_source =
        ns_js_attach_idle(js, ns_microtask_drain_idle, js);
}

/* Runs pending jobs in a time/job-bounded slice, rescheduling leftovers; logs errors. */
void
ns_drain_microtasks(ns_js *js)
{
    if (!js || js->halted || js->draining_microtasks) return;
    js->draining_microtasks = TRUE;
    ns_budget_guard g = {0};
    ns_js_budget_push(js, &g);
    JSContext *ctx_out = NULL;
    int r = 0;
    int jobs = 0;
    gint64 slice_deadline =
        g_get_monotonic_time() + NS_MICROTASK_SLICE_US;
    gint64 trace_start = ns_trace_now();
    js->callback_depth++;
    for (;;) {
        if (js->eval_deadline_us != 0 &&
            g_get_monotonic_time() > js->eval_deadline_us)
            break;
        if (jobs >= NS_MICROTASK_SLICE_JOBS ||
            g_get_monotonic_time() >= slice_deadline)
            break;
        if ((r = JS_ExecutePendingJob(js->rt, &ctx_out)) <= 0)
            break;
        jobs++;
    }
    js->callback_depth--;
    if (jobs > 0)
        ns_trace_completef("script", "microtasks", trace_start, "%d jobs",
                           jobs);
    if (r < 0 && js->log_cb) {
        char *msg = NULL;
        if (ctx_out) {
            JSValue ex = JS_GetException(ctx_out);
            const char *raw = JS_ToCString(ctx_out, ex);
            JSValue stack = JS_GetPropertyStr(ctx_out, ex, "stack");
            const char *stack_s = JS_IsUndefined(stack) ? NULL :
                                  JS_ToCString(ctx_out, stack);
            msg = g_strdup_printf("[error] microtask threw: %s%s%s",
                raw ? raw : "(no message)",
                stack_s ? "\n" : "", stack_s ? stack_s : "");
            if (raw) JS_FreeCString(ctx_out, raw);
            if (stack_s) JS_FreeCString(ctx_out, stack_s);
            JS_FreeValue(ctx_out, stack);
            JS_FreeValue(ctx_out, ex);
        } else {
            msg = g_strdup("[error] microtask threw");
        }
        js->log_cb(msg, js->log_user_data);
        g_free(msg);
    }
    ns_js_budget_pop(js, &g);
    js->draining_microtasks = FALSE;
    if (JS_IsJobPending(js->rt)) {
        ns_schedule_microtask_drain(js);
    } else {
        ns_storage_drain_deferred_events(js);
        if (js->callback_depth == 0)
            ns_js_report_pending_rejections(js);
    }
}

static void ns_storage_flush(ns_js *js);
static void ns_storage_schedule_flush(ns_js *js);
static gboolean ns_timer_fire(gpointer data);

/* Fires up to 8 overdue zero-delay timeouts in id order when no script is on the stack. */
static void
ns_js_run_due_timers(ns_js *js)
{
    if (!js || !js->ctx || js->halted || js->in_pump ||
        js->dispatch_depth > 0 || js->running_due_timers ||
        js->iframe_load_depth > 0 || js->callback_depth > 0 ||
        js->eval_depth > 0 || js->n_immediate_timers <= 0)
        return;
    if (ns_engine_in_blocking_fetch()) return;
    gint64 now = g_get_monotonic_time();
    int due_ids[8];
    int n_due = 0;
    GHashTableIter it;
    gpointer k, v;
    g_hash_table_iter_init(&it, js->timers);
    while (g_hash_table_iter_next(&it, &k, &v)) {
        ns_timer *t = v;
        if (!t->immediate || t->firing || !t->glib_source || t->due_us > now)
            continue;
        if (n_due < 8) {
            due_ids[n_due++] = t->id;
        } else {
            int max_i = 0;
            for (int i = 1; i < n_due; i++)
                if (due_ids[i] > due_ids[max_i]) max_i = i;
            if (t->id < due_ids[max_i]) due_ids[max_i] = t->id;
        }
    }
    if (n_due == 0) return;
    for (int i = 1; i < n_due; i++)
        for (int j = i; j > 0 && due_ids[j] < due_ids[j - 1]; j--) {
            int tmp = due_ids[j];
            due_ids[j] = due_ids[j - 1];
            due_ids[j - 1] = tmp;
        }
    js->running_due_timers = TRUE;
    for (int i = 0; i < n_due; i++) {
        ns_timer *t = g_hash_table_lookup(js->timers,
                                          GINT_TO_POINTER(due_ids[i]));
        if (!t || !t->glib_source) continue;
        ns_js_source_remove(js, t->glib_source);
        t->glib_source = 0;
        if (ns_timer_fire(t) == G_SOURCE_CONTINUE) {
            t = g_hash_table_lookup(js->timers,
                                    GINT_TO_POINTER(due_ids[i]));
            if (t && !t->glib_source)
                t->glib_source = ns_js_attach_timeout(js, 0, ns_timer_fire, t);
        }
    }
    js->running_due_timers = FALSE;
}

typedef struct {
    JSContext *ctx;
    JSJobFunc *run;
    int argc;
    JSValue argv[3];
} ns_message_task;

static void
ns_message_task_free(ns_message_task *t)
{
    for (int i = 0; i < t->argc; i++) JS_FreeValue(t->ctx, t->argv[i]);
    g_free(t);
}

/* Cancels the message-task source and frees all queued message tasks. */
static void
ns_message_tasks_clear(ns_js *js)
{
    if (js->message_task_source) {
        ns_js_source_remove(js, js->message_task_source);
        js->message_task_source = 0;
    }
    if (!js->message_tasks) return;
    ns_message_task *t;
    while ((t = g_queue_pop_head(js->message_tasks)))
        ns_message_task_free(t);
}

static gboolean ns_message_tasks_run(gpointer data);

/* Arms a timeout source to run queued message tasks unless one is pending or running. */
static void
ns_message_tasks_schedule(ns_js *js, guint delay_ms, int priority)
{
    if (js->message_task_source || js->running_message_tasks ||
        !js->message_tasks || g_queue_is_empty(js->message_tasks))
        return;
    GSource *source = g_timeout_source_new(delay_ms);
    g_source_set_priority(source, priority);
    g_source_set_callback(source, ns_message_tasks_run, js, NULL);
    js->message_task_source = g_source_attach(source, js->main_context);
    g_source_unref(source);
}

/* Queues a job (e.g. postMessage delivery) to run as a separate task with duped args. */
static void
ns_queue_message_task(JSContext *ctx, JSJobFunc *run, int argc,
                      JSValueConst *argv)
{
    ns_js *js = js_from_ctx(ctx);
    if (!js || js->halted) return;
    if (!js->message_tasks) js->message_tasks = g_queue_new();
    ns_message_task *t = g_new0(ns_message_task, 1);
    t->ctx = ctx;
    t->run = run;
    t->argc = MIN(argc, (int)G_N_ELEMENTS(t->argv));
    for (int i = 0; i < t->argc; i++)
        t->argv[i] = JS_DupValue(ctx, argv[i]);
    g_queue_push_tail(js->message_tasks, t);
    ns_message_tasks_schedule(js, 0, G_PRIORITY_DEFAULT - 1);
}

static void ns_drain_mutations(ns_js *js);

/* Runs the currently queued message tasks, draining microtasks after each one. */
static gboolean
ns_message_tasks_run(gpointer data)
{
    ns_js *js = data;
    if (js->halted) {
        js->message_task_source = 0;
        ns_message_tasks_clear(js);
        return G_SOURCE_REMOVE;
    }
    js->message_task_source = 0;
    if (js->in_pump || ns_engine_in_blocking_fetch()) {
        ns_message_tasks_schedule(js, 4, G_PRIORITY_DEFAULT);
        return G_SOURCE_REMOVE;
    }
    guint queued = g_queue_get_length(js->message_tasks);
    js->running_message_tasks = TRUE;
    for (guint i = 0; i < queued && !js->halted; i++) {
        ns_message_task *t = g_queue_pop_head(js->message_tasks);
        if (!t) break;
        JSValue r = t->run(t->ctx, t->argc, (JSValueConst *)t->argv);
        if (JS_IsException(r)) JS_FreeValue(t->ctx, JS_GetException(t->ctx));
        JS_FreeValue(t->ctx, r);
        ns_message_task_free(t);
        ns_drain_microtasks(js);
    }
    js->running_message_tasks = FALSE;
    ns_drain_mutations(js);
    ns_message_tasks_schedule(js, 0, G_PRIORITY_DEFAULT_IDLE);
    return G_SOURCE_REMOVE;
}

/* Drains microtasks, notifies the host of DOM mutation, schedules storage flush and timers. */
static void
ns_drain_mutations(ns_js *js)
{
    ns_drain_microtasks(js);
    if (js->mutated && js->mut_cb)
        js->mut_cb(js->mut_user_data);
    js->mutated = FALSE;
    ns_storage_schedule_flush(js);
    ns_js_run_due_timers(js);
}

/* navigator.hardwareConcurrency: processor count clamped to 1..32. */
static int
ns_nav_hardware_concurrency(void)
{
    int n = (int)g_get_num_processors();
    if (n < 1) n = 1;
    if (n > 32) n = 32;
    return n;
}

/* navigator.deviceMemory: total RAM rounded up to a power-of-two GiB, capped at 4. */
static int
ns_nav_device_memory(void)
{
#ifdef G_OS_WIN32
    MEMORYSTATUSEX status = {0};
    status.dwLength = sizeof status;
    if (GlobalMemoryStatusEx(&status)) {
        double gib = (double)status.ullTotalPhys / (1024.0 * 1024.0 * 1024.0);
        int bucket = 1;
        while ((double)bucket < gib && bucket < 4) bucket *= 2;
        return bucket;
    }
#endif
    return 4;
}

/* Screen size and available work area; uses Win32 system metrics when available. */
static void
ns_nav_screen_metrics(int *width, int *height,
                      int *avail_width, int *avail_height,
                      int *avail_left, int *avail_top)
{
    ns_css_media_device device;
    ns_css_get_media_device(&device);
    *width = (int)device.width;
    *height = (int)device.height;
    *avail_width = *width;
    *avail_height = *height;
    *avail_left = 0;
    *avail_top = 0;
#ifdef G_OS_WIN32
    int screen_width = GetSystemMetrics(SM_CXSCREEN);
    int screen_height = GetSystemMetrics(SM_CYSCREEN);
    if (screen_width > 0) *width = screen_width;
    if (screen_height > 0) *height = screen_height;
    RECT work_area;
    if (SystemParametersInfoW(SPI_GETWORKAREA, 0, &work_area, 0)) {
        *avail_width = work_area.right - work_area.left;
        *avail_height = work_area.bottom - work_area.top;
        *avail_left = work_area.left;
        *avail_top = work_area.top;
    }
#endif
}

/* IdleDeadline.timeRemaining() returning the stashed __tr value (default 50 ms). */
static JSValue
ns_idle_deadline_time_remaining(JSContext *ctx, JSValueConst this_val,
                                int argc, JSValueConst *argv)
{
    (void)argc; (void)argv;
    JSValue v = JS_GetPropertyStr(ctx, this_val, "__tr");
    double tr = 50.0;
    if (JS_IsNumber(v)) JS_ToFloat64(ctx, &tr, v);
    JS_FreeValue(ctx, v);
    return JS_NewFloat64(ctx, tr);
}

static gboolean ns_timer_fire_impl(gpointer data);

/* Timer GSource callback; wraps ns_timer_fire_impl with a trace event when tracing. */
static gboolean
ns_timer_fire(gpointer data)
{
    if (!ns_trace_enabled()) return ns_timer_fire_impl(data);
    ns_timer *t = data;
    const char *kind = t->is_idle ? "idle callback"
                     : t->is_interval ? "setInterval" : "setTimeout";
    char *fn = NULL;
    if (!t->code && !JS_IsUndefined(t->cb) && t->js && t->js->ctx) {
        JSContext *c = t->ctx ? t->ctx : t->js->ctx;
        JSValue name = JS_GetPropertyStr(c, t->cb, "name");
        const char *str = JS_IsString(name) ? JS_ToCString(c, name) : NULL;
        if (str) {
            fn = g_strdup(str);
            JS_FreeCString(c, str);
        }
        JS_FreeValue(c, name);
    }
    char *detail = g_strdup_printf("%s %d (%d ms) %s", kind, t->id,
                                   t->interval_ms,
                                   fn && *fn ? fn : t->code ? "<code>" : "");
    gint64 start = ns_trace_now();
    gboolean keep = ns_timer_fire_impl(data);
    ns_trace_complete("script", "timer", start, detail);
    g_free(detail);
    g_free(fn);
    return keep;
}

/* Runs a timer/idle callback in its frame's realm, then reschedules or removes it. */
static gboolean
ns_timer_fire_impl(gpointer data)
{
    ns_timer *t = data;
    ns_js *js = t->js;
    if (js->halted) {
        t->glib_source = 0;
        g_hash_table_remove(js->timers, GINT_TO_POINTER(t->id));
        return G_SOURCE_REMOVE;
    }
    gboolean idle_expired = t->is_idle && t->idle_deadline_us > 0 &&
                            g_get_monotonic_time() >= t->idle_deadline_us;
    if (js->in_pump)
        return G_SOURCE_CONTINUE;
    if (ns_engine_in_blocking_fetch() && !idle_expired)
        return G_SOURCE_CONTINUE;
    ns_node *timer_frame = t->frame;
    if (timer_frame &&
        ns_node_root(timer_frame) != ns_node_root(js->current_doc)) {
        t->glib_source = 0;
        g_hash_table_remove(js->timers, GINT_TO_POINTER(t->id));
        return G_SOURCE_REMOVE;
    }
    JSContext *callback_ctx = t->ctx ? t->ctx : js->ctx;
    if (timer_frame) {
        JSContext *current_realm = ns_js_node_realm_context(js, timer_frame);
        if (current_realm) callback_ctx = current_realm;
    }
    JSContext *previous_ctx = js->ctx;
    ns_node *previous_doc = js->current_doc;
    ns_node *previous_frame = js->raf_frame_ctx;
    char *previous_url = js->current_url;
    js->ctx = callback_ctx;
    if (timer_frame) {
        ns_node *frame_doc = ns_iframe_document_node(timer_frame);
        if (frame_doc) js->current_doc = frame_doc;
        js->raf_frame_ctx = timer_frame;
        const char *frame_url = ns_element_get_attr(timer_frame,
                                                     "data-nd-frame-url");
        js->current_url = g_strdup(frame_url ? frame_url : "");
    }
    t->firing = TRUE;
    int timer_id = t->id;
    gboolean is_interval = t->is_interval;
    int prev_nesting = js->timer_nesting_level;
    js->timer_nesting_level = t->nesting_level;
    ns_budget_guard bg = {0};
    ns_js_budget_push(js, &bg);

    JSValue cb = JS_IsUndefined(t->cb) ? JS_UNDEFINED
                                       : JS_DupValue(callback_ctx, t->cb);
    char *code = t->code ? g_strdup(t->code) : NULL;
    int n_extra = t->extra_args_count;
    JSValue *extra = NULL;
    if (n_extra > 0) {
        extra = g_new(JSValue, n_extra);
        for (int i = 0; i < n_extra; i++)
            extra[i] = JS_DupValue(callback_ctx, t->extra_args[i]);
    }

    JSValue ret;
    js->callback_depth++;
    if (code) {
        ret = JS_Eval(callback_ctx, code, strlen(code), "<timer>",
                      JS_EVAL_TYPE_GLOBAL);
    } else if (t->is_idle) {
        JSValue deadline = JS_NewObject(callback_ctx);
        JS_SetPropertyStr(callback_ctx, deadline, "didTimeout",
                          idle_expired ? JS_TRUE : JS_FALSE);
        JS_DefinePropertyValueStr(callback_ctx, deadline, "__tr",
                                  JS_NewFloat64(callback_ctx, idle_expired ? 0.0 : 50.0), 0);
        JS_SetPropertyStr(callback_ctx, deadline, "timeRemaining",
                          JS_NewCFunction(callback_ctx, ns_idle_deadline_time_remaining,
                                          "timeRemaining", 0));
        JSValueConst args[1] = { deadline };
        ret = JS_Call(callback_ctx, cb, JS_UNDEFINED, 1, args);
        JS_FreeValue(callback_ctx, deadline);
    } else if (n_extra > 0) {
        ret = JS_Call(callback_ctx, cb, JS_UNDEFINED, n_extra, extra);
    } else {
        ret = JS_Call(callback_ctx, cb, JS_UNDEFINED, 0, NULL);
    }

    js->callback_depth--;
    JS_FreeValue(callback_ctx, cb);
    g_free(code);
    if (extra) {
        for (int i = 0; i < n_extra; i++)
            JS_FreeValue(callback_ctx, extra[i]);
        g_free(extra);
    }
    ns_js_budget_pop(js, &bg);
    js->timer_nesting_level = prev_nesting;
    if (JS_IsException(ret)) {
        JSValue ex = JS_GetException(callback_ctx);
        const char *msg = JS_ToCString(callback_ctx, ex);
        JSValue stack = JS_GetPropertyStr(callback_ctx, ex, "stack");
        const char *stk = JS_IsUndefined(stack) ? NULL : JS_ToCString(callback_ctx, stack);
        if (msg && js->log_cb) {
            char *line = g_strdup_printf("JS error in timer: %s%s%s",
                msg, stk ? "\n" : "", stk ? stk : "");
            js->log_cb(line, js->log_user_data);
            g_free(line);
        }
        if (stk) JS_FreeCString(callback_ctx, stk);
        JS_FreeValue(callback_ctx, stack);
        if (msg) JS_FreeCString(callback_ctx, msg);
        ns_js_report_uncaught(js, ex, js->current_url);
        JS_FreeValue(callback_ctx, ex);
    }
    JS_FreeValue(callback_ctx, ret);
    ns_drain_mutations(js);
    if (timer_frame) {
        g_free(js->current_url);
        js->current_url = previous_url;
    }
    js->raf_frame_ctx = previous_frame;
    js->current_doc = previous_doc;
    js->ctx = previous_ctx;
    t = g_hash_table_lookup(js->timers, GINT_TO_POINTER(timer_id));
    if (!t) return G_SOURCE_REMOVE;
    t->firing = FALSE;
    if (!is_interval) {
        t->glib_source = 0;
        g_hash_table_remove(js->timers, GINT_TO_POINTER(timer_id));
        return G_SOURCE_REMOVE;
    }
    if (t->interval_ms < 4) {
        t->interval_ms = 4;
        t->glib_source = ns_js_attach_timeout(js, 4, ns_timer_fire, t);
        return G_SOURCE_REMOVE;
    }
    return G_SOURCE_CONTINUE;
}

/* True when the timer's this-window has a document no longer in the page. */
static gboolean
ns_timer_this_is_detached_window(ns_js *js, JSContext *ctx,
                                 JSValueConst this_val)
{
    if (!js || !JS_IsObject(this_val)) return FALSE;
    JSValue docv = JS_GetPropertyStr(ctx, this_val, "document");
    const ns_node *doc = ns_unwrap_element(docv);
    JS_FreeValue(ctx, docv);
    if (!doc || doc == js->current_doc) return FALSE;
    if (doc->kind != NS_NODE_DOCUMENT || (doc->flags & NS_NODE_FRAGMENT))
        return FALSE;
    const ns_node *page = js->main_document ? js->main_document
                                            : js->current_doc;
    for (const ns_node *p = doc; p; p = p->parent)
        if (p == js->current_doc || p == page) return FALSE;
    return TRUE;
}

/* setTimeout/setInterval: applies HTML nesting clamp and eval CSP; returns timer id. */
static JSValue
ns_js_setTimeout(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv,
                 int is_interval)
{
    if (!js_from_ctx(ctx) || argc < 1) return JS_NewInt32(ctx, 0);
    if (ns_timer_this_is_detached_window(js_from_ctx(ctx), ctx, this_val))
        return JS_NewInt32(ctx, ++js_from_ctx(ctx)->next_timer_id);
    gboolean is_function = JS_IsFunction(ctx, argv[0]);
    char *code = NULL;
    if (!is_function && !ns_js_eval_allowed(ctx))
        return JS_NewInt32(ctx, ++js_from_ctx(ctx)->next_timer_id);
    if (!is_function) {
        const char *s = JS_ToCString(ctx, argv[0]);
        if (!s) return JS_NewInt32(ctx, 0);
        code = g_strdup(s);
        JS_FreeCString(ctx, s);
    }
    int32_t ms = 0;
    if (argc >= 2) JS_ToInt32(ctx, &ms, argv[1]);
    if (ms < 0) ms = 0;

    ns_js *js = js_from_ctx(ctx);
    int nesting = js->timer_nesting_level + 1;
    if (nesting > 5 && ms < 4) ms = 4;

    ns_timer *t = g_new0(ns_timer, 1);
    t->js = js;
    t->ctx = ctx;
    t->frame = ns_js_context_frame(js, ctx);
    t->cb = is_function ? JS_DupValue(ctx, argv[0]) : JS_UNDEFINED;
    t->code = code;
    t->is_interval = is_interval;
    t->nesting_level = nesting;
    t->interval_ms = ms;
    if (is_function && argc > 2) {
        int n_extra = argc - 2;
        if (n_extra > 64) n_extra = 64;
        t->extra_args_count = n_extra;
        t->extra_args = g_new(JSValue, t->extra_args_count);
        for (int i = 0; i < t->extra_args_count; i++)
            t->extra_args[i] = JS_DupValue(ctx, argv[2 + i]);
    }
    t->id = ++js->next_timer_id;
    if (!is_interval && ms <= 1) {
        t->immediate = TRUE;
        t->due_us = g_get_monotonic_time() + (gint64)ms * 1000;
        js->n_immediate_timers++;
    }
    t->glib_source = ns_js_attach_timeout(js, (guint)ms, ns_timer_fire, t);
    g_hash_table_insert(js->timers, GINT_TO_POINTER(t->id), t);
    return JS_NewInt32(ctx, t->id);
}

static JSValue
ns_js_setTimeout_wrap(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    return ns_js_setTimeout(ctx, this_val, argc, argv, 0);
}

static JSValue
ns_js_setInterval_wrap(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    return ns_js_setTimeout(ctx, this_val, argc, argv, 1);
}

/* clearTimeout/clearInterval: cancels and removes the timer by id. */
static JSValue
ns_js_clearTimer(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)
{
    (void)this_val;
    if (!js_from_ctx(ctx) || argc < 1) return JS_UNDEFINED;
    int32_t id = 0;
    JS_ToInt32(ctx, &id, argv[0]);
    ns_timer *t = g_hash_table_lookup(js_from_ctx(ctx)->timers, GINT_TO_POINTER(id));
    if (t) {
        ns_js_source_remove(js_from_ctx(ctx), t->glib_source);
        t->glib_source = 0;
        g_hash_table_remove(js_from_ctx(ctx)->timers, GINT_TO_POINTER(id));
    }
    return JS_UNDEFINED;
}

