/* OrdinaryHasInstance: walks value's prototype chain looking for ctor.prototype. */
static JSValue
ns_ctor_ordinary_has_instance(JSContext *ctx, JSValueConst ctor,
                              JSValueConst value)
{
    if (!JS_IsObject(value)) return JS_FALSE;
    JSValue prototype = JS_GetPropertyStr(ctx, ctor, "prototype");
    if (JS_IsException(prototype)) return prototype;
    if (!JS_IsObject(prototype)) {
        JS_FreeValue(ctx, prototype);
        return JS_ThrowTypeError(ctx,
            "Function has non-object prototype in instanceof check");
    }
    JSValue current = JS_GetPrototype(ctx, value);
    while (JS_IsObject(current)) {
        if (JS_IsStrictEqual(ctx, current, prototype)) {
            JS_FreeValue(ctx, current);
            JS_FreeValue(ctx, prototype);
            return JS_TRUE;
        }
        JSValue next = JS_GetPrototype(ctx, current);
        JS_FreeValue(ctx, current);
        current = next;
    }
    JS_FreeValue(ctx, current);
    JS_FreeValue(ctx, prototype);
    return JS_FALSE;
}

/* Symbol.hasInstance for DOM interfaces: matches native nodes by kind and tag name. */
static JSValue
ns_ctor_hasInstance(JSContext *ctx, JSValueConst this_val,
                     int argc, JSValueConst *argv, int magic)
{
    if (argc < 1 || magic < 0 ||
        magic >= (int)G_N_ELEMENTS(ns_instof_table))
        return JS_FALSE;
    const ns_instof_def *d = &ns_instof_table[magic];
    JSValue global = JS_GetGlobalObject(ctx);
    JSValue native_ctor = JS_GetPropertyStr(ctx, global, d->ctor);
    JS_FreeValue(ctx, global);
    gboolean direct = JS_IsObject(native_ctor) &&
                      JS_IsStrictEqual(ctx, this_val, native_ctor);
    JS_FreeValue(ctx, native_ctor);
    if (!direct)
        return ns_ctor_ordinary_has_instance(ctx, this_val, argv[0]);
    if (d->special == NS_INSTOF_HTMLCOLLECTION)
        return JS_NewBool(ctx, ns_live_collection_kind(argv[0]) == 1);
    if (d->special == NS_INSTOF_NODELIST) {
        if (ns_live_collection_kind(argv[0]) == 0)
            return JS_TRUE;
        if (JS_IsObject(argv[0])) {
            JSValue m = JS_GetPropertyStr(ctx, argv[0], "__nsNodeList");
            int hit = JS_ToBool(ctx, m);
            JS_FreeValue(ctx, m);
            return JS_NewBool(ctx, hit == 1);
        }
        return JS_FALSE;
    }
    const ns_node *n = ns_unwrap_element(argv[0]);
    if (!n) {
        if (d->special == NS_INSTOF_NODE)
            return JS_NewBool(ctx, ns_value_is_attr_node(ctx, argv[0]));
        return JS_FALSE;
    }
    switch (d->special) {
    case NS_INSTOF_NODE:
        return JS_NewBool(ctx, TRUE);
    case NS_INSTOF_ELEMENT:
        return JS_NewBool(ctx, n->kind == NS_NODE_ELEMENT);
    case NS_INSTOF_DOCUMENT:
        return JS_NewBool(ctx, n->kind == NS_NODE_DOCUMENT &&
                               !(n->flags & NS_NODE_FRAGMENT));
    case NS_INSTOF_FRAGMENT:
        return JS_NewBool(ctx, (n->flags & NS_NODE_FRAGMENT) != 0);
    case NS_INSTOF_TEXT:
        return JS_NewBool(ctx, n->kind == NS_NODE_TEXT);
    case NS_INSTOF_COMMENT:
        return JS_NewBool(ctx, n->kind == NS_NODE_COMMENT);
    case NS_INSTOF_CHARDATA:
        return JS_NewBool(ctx, n->kind == NS_NODE_TEXT ||
                               n->kind == NS_NODE_COMMENT);
    case NS_INSTOF_DOCTYPE:
        return JS_NewBool(ctx, n->kind == NS_NODE_DOCTYPE);
    case NS_INSTOF_SHADOW:
        return JS_NewBool(ctx, n->kind == NS_NODE_ELEMENT &&
                          ns_element_get_attr(n, NS_SHADOW_ATTR) != NULL);
    case NS_INSTOF_UNKNOWN: {
        if (n->kind != NS_NODE_ELEMENT || (n->flags & (NS_NODE_SVG_NS | NS_NODE_FOREIGN_NS)))
            return JS_FALSE;
        if (!n->name || ns_ce_name_valid(n->name) ||
            ns_html_tag_has_plain_interface(n->name))
            return JS_FALSE;
        ns_js *_j = js_from_ctx(ctx);
        if (_j && _j->per_tag_protos && g_hash_table_contains(_j->per_tag_protos, n->name))
            return JS_FALSE;
        return JS_TRUE;
    }
    default:
        break;
    }
    if (d->special == NS_INSTOF_HTMLELEMENT)
        return JS_NewBool(ctx, n->kind == NS_NODE_ELEMENT &&
                          !(n->flags & (NS_NODE_SVG_NS | NS_NODE_FOREIGN_NS)));
    if (n->kind != NS_NODE_ELEMENT || !n->name || !d->tags)
        return JS_FALSE;
    if (n->flags & (NS_NODE_SVG_NS | NS_NODE_FOREIGN_NS))
        return JS_FALSE;
    const char *s = d->tags;
    size_t nlen = strlen(n->name);
    while (*s) {
        while (*s == ' ') s++;
        const char *tok = s;
        while (*s && *s != ' ') s++;
        size_t tlen = (size_t)(s - tok);
        if (tlen == nlen && strncmp(tok, n->name, tlen) == 0)
            return JS_TRUE;
    }
    return JS_FALSE;
}

/* Installs Symbol.hasInstance on every constructor in ns_instof_table. */
static void
ns_install_hasinstance(JSContext *ctx, JSValueConst global)
{
    JSValue sym = JS_GetPropertyStr(ctx, global, "Symbol");
    if (!JS_IsObject(sym)) { JS_FreeValue(ctx, sym); return; }
    JSValue hi = JS_GetPropertyStr(ctx, sym, "hasInstance");
    JS_FreeValue(ctx, sym);
    JSAtom hi_atom = JS_ValueToAtom(ctx, hi);
    JS_FreeValue(ctx, hi);
    for (int i = 0; i < (int)G_N_ELEMENTS(ns_instof_table); i++) {
        JSValue ctor = JS_GetPropertyStr(ctx, global, ns_instof_table[i].ctor);
        if (JS_IsObject(ctor)) {
            JSValue fn = JS_NewCFunctionMagic(ctx, ns_ctor_hasInstance,
                "[Symbol.hasInstance]", 1, JS_CFUNC_generic_magic, i);
            JS_DefinePropertyValue(ctx, ctor, hi_atom, fn, JS_PROP_CONFIGURABLE);
        }
        JS_FreeValue(ctx, ctor);
    }
    JS_FreeAtom(ctx, hi_atom);
}

/* Uppercased prefix:name for prefixed elements, or undefined without a prefix. */
static JSValue
ns_element_qualified_upper(JSContext *ctx, const ns_node *n)
{
    const char *pfx = ns_element_get_attr(n, "data-nd-ns-prefix");
    if (!pfx) return JS_UNDEFINED;
    char *q = g_strdup_printf("%s:%s", pfx, n->name);
    char *up = g_ascii_strup(q, -1);
    JSValue v = JS_NewString(ctx, up);
    g_free(q);
    g_free(up);
    return v;
}

static gboolean ns_doc_wrapper_is_xml(JSContext *ctx, JSValueConst doc_val);
static JSValue ns_element_get_ownerDocument(JSContext *ctx, JSValueConst this_val);

/* Element.tagName: qualified name, uppercased only for HTML elements in HTML documents. */
static JSValue
ns_element_get_tagName(JSContext *ctx, JSValueConst this_val)
{
    const ns_node *n = ns_unwrap_element(this_val);
    if (!n || !n->name) return JS_NULL;
    gboolean foreign = (n->flags & (NS_NODE_SVG_NS | NS_NODE_FOREIGN_NS)) != 0;
    JSValue owner_doc = ns_element_get_ownerDocument(ctx, this_val);
    gboolean doc_is_xml = FALSE;
    if (JS_IsObject(owner_doc))
        doc_is_xml = ns_doc_wrapper_is_xml(ctx, owner_doc);
    JS_FreeValue(ctx, owner_doc);
    gboolean is_xml = foreign || doc_is_xml;
    if (is_xml) {
        const char *pfx = ns_element_get_attr(n, "data-nd-ns-prefix");
        if (pfx && *pfx) {
            char *q = g_strdup_printf("%s:%s", pfx, n->name);
            JSValue v = JS_NewString(ctx, q);
            g_free(q);
            return v;
        }
        return JS_NewString(ctx, n->name);
    }
    if (n->kind == NS_NODE_ELEMENT) {
        JSValue q = ns_element_qualified_upper(ctx, n);
        if (!JS_IsUndefined(q)) return q;
    }
    char *up = g_ascii_strup(n->name, -1);
    JSValue v = JS_NewString(ctx, up);
    g_free(up);
    return v;
}

/* accessKeyLabel: the accesskey value when it is a single character, else "". */
static JSValue
ns_element_get_accessKeyLabel(JSContext *ctx, JSValueConst this_val)
{
    const ns_node *n = ns_unwrap_element(this_val);
    const char *key = n ? ns_element_get_attr(n, "accesskey") : NULL;
    if (!key || !g_utf8_validate(key, -1, NULL) || g_utf8_strlen(key, -1) != 1)
        return JS_NewString(ctx, "");
    return JS_NewString(ctx, key);
}

/* Element.localName, stripping any prefix from namespaced foreign elements. */
static JSValue
ns_element_get_localName(JSContext *ctx, JSValueConst this_val)
{
    const ns_node *n = ns_unwrap_element(this_val);
    if (!n || !n->name) return JS_NULL;
    if ((n->flags & (NS_NODE_SVG_NS | NS_NODE_FOREIGN_NS)) &&
        ns_element_get_attr(n, "data-nd-ns-uri")) {
        const char *colon = strchr(n->name, ':');
        if (colon) return JS_NewString(ctx, colon + 1);
    }
    return JS_NewString(ctx, n->name);
}

/* Element.prefix from the stored namespace prefix or a prefixed foreign name. */
static JSValue
ns_element_get_prefix(JSContext *ctx, JSValueConst this_val)
{
    const ns_node *n = ns_unwrap_element(this_val);
    if (!n || !n->name) return JS_NULL;
    if (n->kind == NS_NODE_ELEMENT) {
        const char *stored = ns_element_get_attr(n, "data-nd-ns-prefix");
        if (stored) return JS_NewString(ctx, stored);
    }
    if ((n->flags & (NS_NODE_SVG_NS | NS_NODE_FOREIGN_NS)) &&
        ns_element_get_attr(n, "data-nd-ns-uri")) {
        const char *colon = strchr(n->name, ':');
        if (colon)
            return JS_NewStringLen(ctx, n->name, (size_t)(colon - n->name));
    }
    return JS_NULL;
}

