/* Marks layout dirty if web font loads changed the font generation since last layout. */
static void
ns_js_note_font_loads(ns_js *js)
{
    if (js->layout_root && js->layout_font_generation != ns_font_generation())
        ns_js_note_layout_unscoped(js, G_STRFUNC);
}

/* Forces a synchronous layout via the embedder, tracing reflows over 50 us. */
static void
ns_js_flush_layout_from(ns_js *js, const char *api)
{
    if (!js || !js->layout_flush_cb || js->in_layout_flush) return;
    ns_js_note_font_loads(js);
    gint64 start = ns_trace_now();
    js->in_layout_flush = TRUE;
    js->layout_flush_cb(js->layout_flush_user_data);
    js->in_layout_flush = FALSE;
    if (start && g_get_monotonic_time() - start >= 50)
        ns_trace_complete("layout", "forced reflow", start, api);
}

void
ns_js_set_style_flush_cb(ns_js *js, ns_js_layout_flush_cb cb, gpointer user_data)
{
    if (!js) return;
    js->style_flush_cb = cb;
    js->style_flush_user_data = user_data;
}

/* Forces a style flush (falls back to a full layout flush when no style callback). */
static void
ns_js_flush_style(ns_js *js)
{
    if (!js || js->in_layout_flush) return;
    if (!js->style_flush_cb) {
        ns_js_flush_layout(js);
        return;
    }
    ns_js_note_font_loads(js);
    js->in_layout_flush = TRUE;
    js->style_flush_cb(js->style_flush_user_data);
    js->in_layout_flush = FALSE;
}

const char *
ns_js_current_url(const ns_js *js)
{
    return js && js->current_url ? js->current_url : "";
}

